            self.permissions[role] = {}
        self.permissions[role][permission] = effect

    def assign_user_role(self, user, role):
        if not isinstance(user, str) or not user:
            raise ValueError("User must be a non-empty string")
        if not isinstance(role, str) or not role:
            raise ValueError("Role must be a non-empty string")

        if user not in self.user_roles:
            self.user_roles[user] = set()
        self.user_roles[user].add(role)

    def _get_all_roles(self, role):
        """
        Recursively gets all roles inherited by the given role.
        Raises CyclicRoleInheritanceError if a cycle is detected.
        """
        visited = set()
        result = set()

        def dfs(current_role):
            if current_role in visited:
                # If we've seen this role in the current path, it's a cycle.
                # However, since we use a global visited set for the whole traversal, 
                # we need to be careful. A simple visited set prevents re-processing 
                # but doesn't distinguish between "already processed" and "in current path". 
                # For cycle detection, we need to track the current path.
                pass

        # Better approach: use a path-based detection
        def dfs_path(current_role, path):
            if current_role in path:
                raise CyclicRoleInheritanceError(f"Cycle detected involving role '{current_role}'")
            if current_role in result:
                return

            path.add(current_role)
            result.add(current_role)

            for parent in self.roles.get(current_role, []):
                dfs_path(parent, path)

            path.remove(current_role)

        dfs_path(role, set())
        return result

    def evaluate(self, user, permission):
        if not isinstance(user, str) or not user:
            return False
        if not isinstance(permission, str) or not permission:
            return False

        roles = set()
        for r in self.user_roles.get(user, []):
            try:
                roles.update(self._get_all_roles(r))
            except CyclicRoleInheritanceError:
                # Fail closed on cycle detection
                return False

        has_allow = False
        has_deny = False

        for r in roles:
            eff = self.permissions.get(r, {}).get(permission)
            if eff == "ALLOW":
                has_allow = True
            elif eff == "DENY":
                has_deny = True

        # Explicit DENY takes precedence over ALLOW
        if has_deny:
            return False
        if has_allow:
            return True
        return False
